package br.com.mecaniQA.api.Mappers;
import java.sql.*; import br.com.mecaniQA.api.model.*; import br.com.mecaniQA.api.Enums.*;
public class VeiculoResultSetMapper implements ResultSetMapper<Veiculo>{public Veiculo map(ResultSet r)throws SQLException{Cliente c=new Cliente();c.setIdCliente(r.getLong("id_cliente"));Veiculo x=new Veiculo();x.setIdVeiculo(r.getLong("id_veiculo"));x.setCliente(c);x.setPlaca(r.getString("placa"));x.setMarcaModelo(r.getString("marca_modelo"));x.setAno(r.getInt("ano"));x.setCor(r.getString("cor"));x.setNumeroMotor(r.getString("numero_motor"));x.setNumeroChassi(r.getString("numero_chassi"));x.setQuilometragem(r.getDouble("quilometragem"));x.setObservacoes(r.getString("observacoes"));Timestamp t=r.getTimestamp("data_atualizacao");x.setDataAtualizacao(t==null?null:t.toLocalDateTime());return x;}}
